const channel = $('Get Channel').first().json.items[0];
const raw = $input.first().json.items || [];
if (!raw.length) throw new Error('No video data returned.');

const avg = a => a.length ? a.reduce((x, y) => x + y, 0) / a.length : 0;
const median = a => {
  const s = [...a].sort((x, y) => x - y);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};
const round = (n, d = 2) => Math.round(n * Math.pow(10, d)) / Math.pow(10, d);
const fmt = n => Number(n || 0).toLocaleString('en-US');
const dur = iso => {
  const m = /PT(?:([0-9]+)H)?(?:([0-9]+)M)?(?:([0-9]+)S)?/.exec(iso || '');
  return m ? (+m[1] || 0) * 3600 + (+m[2] || 0) * 60 + (+m[3] || 0) : 0;
};

const videos = raw.map(v => {
  const s = v.statistics || {};
  const views = +s.viewCount || 0, likes = +s.likeCount || 0, comments = +s.commentCount || 0;
  const d = new Date(v.snippet.publishedAt);
  return {
    title: v.snippet.title,
    url: 'https://www.youtube.com/watch?v=' + v.id,
    date: v.snippet.publishedAt.slice(0, 10),
    weekday: d.getUTCDay(),
    views, likes, comments,
    minutes: round(dur(v.contentDetails.duration) / 60, 1),
    engagement: views ? round((likes + comments) / views * 100) : 0
  };
}).sort((a, b) => b.date.localeCompare(a.date));

const byViews = [...videos].sort((a, b) => b.views - a.views);
const byEng = [...videos].filter(v => v.views >= 100).sort((a, b) => b.engagement - a.engagement);

const times = videos.map(v => new Date(v.date).getTime());
const gaps = [];
for (let i = 0; i < times.length - 1; i++) gaps.push((times[i] - times[i + 1]) / 86400000);

const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const dayStats = days.map((name, i) => {
  const g = videos.filter(v => v.weekday === i);
  return { day: name, uploads: g.length, avgViews: Math.round(avg(g.map(v => v.views))) };
}).filter(x => x.uploads > 0).sort((a, b) => b.avgViews - a.avgViews);

const st = channel.statistics || {};
const L = [];
L.push('CHANNEL: ' + channel.snippet.title + ' (' + (channel.snippet.customUrl || '') + ')');
L.push('Subscribers: ' + (st.hiddenSubscriberCount ? 'hidden' : fmt(st.subscriberCount)) + ' | Total views: ' + fmt(st.viewCount) + ' | Videos: ' + fmt(st.videoCount));
L.push('');
L.push('LAST ' + videos.length + ' UPLOADS (' + videos[videos.length - 1].date + ' to ' + videos[0].date + ')');
L.push('Median views: ' + fmt(Math.round(median(videos.map(v => v.views)))));
L.push('Average views: ' + fmt(Math.round(avg(videos.map(v => v.views)))));
L.push('Average engagement: ' + round(avg(videos.map(v => v.engagement))) + '% (likes + comments / views)');
L.push('Average length: ' + round(avg(videos.map(v => v.minutes)), 1) + ' min');
L.push('Upload frequency: one every ' + round(avg(gaps), 1) + ' days');
L.push('');
L.push('TOP 5 BY VIEWS');
byViews.slice(0, 5).forEach((v, i) => L.push((i + 1) + '. ' + v.title + ' - ' + fmt(v.views) + ' views, ' + v.engagement + '% eng.'));
L.push('');
L.push('TOP 5 BY ENGAGEMENT');
byEng.slice(0, 5).forEach((v, i) => L.push((i + 1) + '. ' + v.title + ' - ' + v.engagement + '% (' + fmt(v.views) + ' views)'));
L.push('');
L.push('BEST UPLOAD DAYS (by avg views, UTC)');
dayStats.slice(0, 3).forEach(d => L.push('- ' + d.day + ': ' + fmt(d.avgViews) + ' avg views (' + d.uploads + ' uploads)'));

return [{
  json: {
    report: L.join('\n'),
    topByViews: byViews.slice(0, 5),
    topByEngagement: byEng.slice(0, 5),
    weekdayStats: dayStats,
    allVideos: videos
  }
}];
